122	/**
123	 * Claim a task (prevents duplicate agent work).
124	 * @param {string} taskId - unique task identifier
125	 * @param {string} agentName - agent claiming the task
126	 * @param {string} [description] - what the task is
127	 * @returns {Promise<{ ok: boolean, taskId: string, claimedBy: string } | { error: string }>}
128	 */
129	async function claimTask(taskId, agentName, description) {
130	  try {
131	    const res = await fetch(`${POLYGLOT_URL}/api/claims`, {
132	      method: 'POST',
133	      headers: { 'Content-Type': 'application/json' },
134	      body: JSON.stringify({ taskId, agentName, description }),
135	    })
136	    return await res.json()
137	  } catch {
138	    return { error: 'Polyglot not reachable' }
139	  }
140	}
141	
142	/**
143	 * Release/complete a claimed task.
144	 * @param {string} taskId
145	 * @param {'completed' | 'released' | 'failed'} status
146	 * @param {string} [result] - outcome description
147	 */
148	async function releaseClaim(taskId, status = 'completed', result) {
149	  try {
150	    const res = await fetch(`${POLYGLOT_URL}/api/claims/${encodeURIComponent(taskId)}`, {
151	      method: 'PUT',
152	      headers: { 'Content-Type': 'application/json' },
153	      body: JSON.stringify({ status, result }),
154	    })
155	    return await res.json()
156	  } catch {
157	    return { error: 'Polyglot not reachable' }
158	  }
159	}
160	
161	/**
162	 * Check if a task is already claimed.
163	 * @param {string} taskId
164	 * @returns {Promise<{ claimed: boolean, agentName?: string }>}
165	 */
166	async function isTaskClaimed(taskId) {
167	  try {
168	    const res = await fetch(`${POLYGLOT_URL}/api/claims/${encodeURIComponent(taskId)}`)
169	    return await res.json()
170	  } catch {
171	    return { claimed: false }
172	  }
173	}
174	
175	/**
176	 * Get recommended model tier for a task.
177	 * @param {string} agentName
178	 * @param {string} [taskDescription]
179	 * @returns {Promise<{ model: string, tier: string, reason: string }>}
180	 */
181	async function getRecommendedModel(agentName, taskDescription) {
182	  try {
183	    const res = await fetch(`${POLYGLOT_URL}/api/routing/recommend`, {
184	      method: 'POST',
185	      headers: { 'Content-Type': 'application/json' },
186	      body: JSON.stringify({ agentName, taskDescription }),
187	    })
188	    return await res.json()
189	  } catch {
190	    return { model: 'sonnet', tier: 'medium', reason: 'fallback (hub unreachable)' }
191	  }
192	}
193	
194	/**
195	 * Record a learning event (agent performance tracking).
196	 * @param {string} agentName
197	 * @param {string} taskType
198	 * @param {{ success: boolean, duration?: number, tokens?: number, cost?: number }} outcome
199	 */
200	async function recordAgentLearning(agentName, taskType, outcome) {
201	  try {
202	    const res = await fetch(`${POLYGLOT_URL}/api/learning/record`, {
203	      method: 'POST',
204	      headers: { 'Content-Type': 'application/json' },
205	      body: JSON.stringify({ agentName, taskType, ...outcome }),
206	    })
207	    return await res.json()
208	  } catch {
209	    return { error: 'Polyglot not reachable' }
210	  }
211	}
212	
213	/**
214	 * Get the best agent for a task type (based on learning data).
215	 * @param {string} taskType - e.g. 'copy', 'build', 'test', 'debug', 'review'
216	 * @returns {Promise<{ recommendation: string | null, successRate: number }>}
217	 */
218	async function getBestAgent(taskType) {
219	  try {
220	    const res = await fetch(`${POLYGLOT_URL}/api/learning/route/${encodeURIComponent(taskType)}`)
221	    return await res.json()
222	  } catch {
223	    return { recommendation: null, message: 'Hub unreachable' }
224	  }
225	}
226	
227	module.exports = {
228	  callAgent, listAgents, isOnline, listCategories, listTemplates,
229	  // Claims system
230	  claimTask, releaseClaim, isTaskClaimed,
231	  // Model routing
232	  getRecommendedModel,
233	  // Learning system
234	  recordAgentLearning, getBestAgent,
235	}
