25	app.use((req, res, next) => {
26	  const origin = req.headers.origin;
27	  if (origin && ALLOWED_ORIGINS.has(origin)) {
28	    res.header('Access-Control-Allow-Origin', origin);
29	  } else if (!origin) {
30	    // Same-origin or non-browser client — no CORS header needed
31	  }
32	  res.header('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
