50	// ── Security: Rate limiting (in-memory, simple) ──────────────────────────────
51	const rateLimitMap = new Map();
52	const RATE_LIMIT_WINDOW = 60_000; // 1 minute
53	const RATE_LIMITS = {
54	  heavy: 10,   // AI chat, orchestration runs, playground — 10/min
55	  write: 60,   // file writes, creates, deletes — 60/min
56	  read: 200,   // reads, listings — 200/min
57	};
58	
59	function rateLimit(tier) {
60	  const max = RATE_LIMITS[tier] || RATE_LIMITS.read;
61	  return (req, res, next) => {
62	    const key = `${tier}:${req.ip}`;
63	    const now = Date.now();
64	    let entry = rateLimitMap.get(key);
65	    if (!entry || now - entry.start > RATE_LIMIT_WINDOW) {
66	      entry = { start: now, count: 0 };
67	      rateLimitMap.set(key, entry);
68	    }
69	    entry.count++;
70	    if (entry.count > max) {
71	      return res.status(429).json({ error: `Rate limit exceeded (${max}/${RATE_LIMIT_WINDOW / 1000}s)` });
72	    }
73	    next();
74	  };
75	}
76	
77	// Cleanup stale entries every 5 minutes
78	setInterval(() => {
79	  const now = Date.now();
80	  for (const [key, entry] of rateLimitMap) {
81	    if (now - entry.start > RATE_LIMIT_WINDOW * 2) rateLimitMap.delete(key);
82	  }
83	}, 300_000);
84	
