1821	  return new Promise((resolve, reject) => {
1822	    const claudePath = process.env.CLAUDE_PATH || 'claude';
1823	    const childEnv = { ...process.env, HOME: os.homedir() };
1824	    delete childEnv.CLAUDECODE;
1825	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
1826	    let out = '', err = '';
1827	    let killed = false;
1828	
1829	    const timer = setTimeout(() => {
1830	      killed = true;
1831	      proc.kill('SIGTERM');
1832	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
1833	    }, timeoutMs);
1834	
1835	    proc.stdout.on('data', d => { out += d.toString(); });
1836	    proc.stderr.on('data', d => { err += d.toString(); });
1837	    proc.on('close', code => {
1838	      clearTimeout(timer);
1839	      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
1840	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
1841	      else resolve(out.trim());
1842	    });
1843	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
1844	    proc.stdin.write(prompt, 'utf8');
1845	    proc.stdin.end();
1846	  });
1847	}
